var o=`1361-arepa-de-huevo`;var i=`world-1361`;var a=`CO`;var r=`south-america`;var n=4;var s=52;var u={en:`Arepa de Huevo`,ua:`Арепа з яйцем`};var l={en:`Arepa de Huevo is a dish from Colombia featuring arepa flour, chicken egg. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Арепа з яйцем, страва кухні країни Колумбія з такими основними складниками: борошно для ареп, куряче яйце. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Mix the corn flour with the measured water and salt until a soft cohesive, non-sticky masa forms. Rest covered for about 10 minutes; this gluten-free dough does not become elastic like wheat dough.`,ua:`Змішайте кукурудзяне борошно із зазначеною водою й сіллю до м’якої цілісної маси, що не липне. Накрийте на приблизно 10 хвилин; таке безглютенове тісто не стає еластичним, як пшеничне.`,t:[`mixing`,`kneading`,`resting-dough`],m:12,i:[[`arepa-flour`,450,`g`],[`water`,560,`ml`],[`table-salt`,8,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 10 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 10 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:10,i:[[`canola-oil`,80,`ml`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:8,i:[[`chicken-egg`,4,`pcs`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 10 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 10 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:10,i:[[`canola-oil`,800,`ml`]]}];var d={slug:o,id:i,country:`CO`,region:r,servings:4,minutes:52,title:u,text:l,steps:h};export{a as country,d as default,i as id,s as minutes,r as region,n as servings,o as slug,h as steps,l as text,u as title};